  // 5. Nama di cover, hero, dan closing
  html = html.replace(/<span id="cover-bride"[^>]*>[\s\S]*?<\/span\s*>/, `<span id="cover-bride">${esc(groomName)}</span>`);
  html = html.replace(/<span id="cover-groom"[^>]*>[\s\S]*?<\/span\s*>/, `<span id="cover-groom">${esc(brideName)}</span>`);
  html = html.replace(/<span id="hero-bride"[^>]*>[\s\S]*?<\/span\s*>/, `<span id="hero-bride" class="hero-name">${esc(groomName)}</span>`);
