  // 11. Gaya tambahan untuk Instagram penutup
  html += `<style id="taman-extra-style">#closing-social{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin-top:14px}.closing-social{display:inline-flex;align-items:center;padding:7px 16px;border-radius:999px;border:1px solid rgba(120,100,60,.32);background:rgba(255,253,246,.72);color:var(--ink-600);font-family:var(--serif);font-size:14px;text-decoration:none;transition:color .2s ease,border-color .2s ease}.closing-social:hover{border-color:var(--rose-400);color:var(--rose-500)}</style>`;

  // 12. Hapus badge undangan gratis
